  sources, status
) values
  ('Coco Tang', 'VIETNAMESE', '{}', 3, 'spinningfields', 'manchester', 53.4796, -2.2493, false, '{none}', '{}', 'Eighteen years of running Nottingham''s Byard Lane before Manchester got a look — Vietnamese café by day, a cocktail room and late kitchen once the Bridge Street lights come on.', '{"morning","afternoon","evening","late"}', 82, 'Not yet Gate 1 reviewed — raw daily research candidate, no independent verification pass has run on it.', null, null, null, '[{"note":"Raw daily-research candidate from docs/data/venue-suggestions.json, suggested 2026-09-22 — not yet independently re-verified (the review pass has stalled since 2026-09-17/18). Synced 2026-09-29 for direct human review at /admin/review."}]'::jsonb, 'pending_review'),
  ('Stile Napoletano', 'PIZZERIA', '{}', 2, 'chester', 'cheshire', 53.1898, -2.8936, false, '{none}', '{}', 'Giacomo''s dough gets its own slow Neapolitan ferment on Watergate Street — one of Europe''s fifty best pizzerias by outside reckoning, and still just the one room to prove it in.', '{"afternoon","evening"}', 78, 'Not yet Gate 1 reviewed — raw daily research candidate, no independent verification pass has run on it.', null, null, null, '[{"note":"Raw daily-research candidate from docs/data/venue-suggestions.json, suggested 2026-09-23 — not yet independently re-verified (the review pass has stalled since 2026-09-17/18). Synced 2026-09-29 for direct human review at /admin/review."}]'::jsonb, 'pending_review'),
